INSERT INTO "statutory_rule_sets" ("statute", "jurisdiction", "version", "valid_from", "valid_to", "values", "source", "verify", "status", "law_version", "published_at") VALUES ('IN.LWF', 'IN-TN', '2026-v3', '2026-12-01', NULL, '{"kind":"lwf","months":[12],"employee":"20","employer":"40","minDaysEmployed":30,"supervisorAbove":"15000"}', 'Tamil Nadu Labour Welfare Fund Act 1972 as applied by the Board (G.O. No. 161 of 02.12.2022): 20 employee / 40 employer a year in December, for people employed 30 days or more; managers and supervisors earning above 15,000 a month are not covered (review M3, answer 2762: HR marks the job as manager or supervisor).', true, 'published', 'OLD-ACT', CURRENT_TIMESTAMP)
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'December, a supervisor on 15,000: 20 / 40', 'lwf', '{"month":12,"daysEmployed":200,"wage":"15000","supervisory":true}', '{"employee":"20","employer":"40"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.LWF' AND "jurisdiction" = 'IN-TN' AND "version" = '2026-v3' AND NOT EXISTS (SELECT 1 FROM "statutory_golden_cases" g WHERE g."rule_set_id" = "statutory_rule_sets"."id" AND g."name" = 'December, a supervisor on 15,000: 20 / 40');
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'December, a supervisor above 15,000: none', 'lwf', '{"month":12,"daysEmployed":200,"wage":"15001","supervisory":true}', '{"employee":"0","employer":"0"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.LWF' AND "jurisdiction" = 'IN-TN' AND "version" = '2026-v3' AND NOT EXISTS (SELECT 1 FROM "statutory_golden_cases" g WHERE g."rule_set_id" = "statutory_rule_sets"."id" AND g."name" = 'December, a supervisor above 15,000: none');
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'December, not a supervisor above 15,000: 20 / 40', 'lwf', '{"month":12,"daysEmployed":200,"wage":"40000","supervisory":false}', '{"employee":"20","employer":"40"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.LWF' AND "jurisdiction" = 'IN-TN' AND "version" = '2026-v3' AND NOT EXISTS (SELECT 1 FROM "statutory_golden_cases" g WHERE g."rule_set_id" = "statutory_rule_sets"."id" AND g."name" = 'December, not a supervisor above 15,000: 20 / 40');
INSERT INTO "statutory_rule_sets" ("statute", "jurisdiction", "version", "valid_from", "valid_to", "values", "source", "verify", "status", "law_version", "published_at") VALUES ('IN.LWF', 'IN-DL', '2026-v2', '2026-12-01', NULL, '{"kind":"lwf","months":[6,12],"employee":"0.75","employer":"2.25","supervisorAbove":"2500"}', 'Bombay Labour Welfare Fund Act, 1953 as extended to Delhi (half-yearly, June and December; 0.75 employee, 2.25 employer); supervisors earning above 2,500 a month are not covered (review M3, answer 2762).', true, 'published', 'OLD-ACT', CURRENT_TIMESTAMP)
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'December, a supervisor above 2,500: none', 'lwf', '{"month":12,"wage":"30000","supervisory":true}', '{"employee":"0","employer":"0"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.LWF' AND "jurisdiction" = 'IN-DL' AND "version" = '2026-v2' AND NOT EXISTS (SELECT 1 FROM "statutory_golden_cases" g WHERE g."rule_set_id" = "statutory_rule_sets"."id" AND g."name" = 'December, a supervisor above 2,500: none');
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'December, not a supervisor: 0.75 / 2.25', 'lwf', '{"month":12,"wage":"30000","supervisory":false}', '{"employee":"0.75","employer":"2.25"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.LWF' AND "jurisdiction" = 'IN-DL' AND "version" = '2026-v2' AND NOT EXISTS (SELECT 1 FROM "statutory_golden_cases" g WHERE g."rule_set_id" = "statutory_rule_sets"."id" AND g."name" = 'December, not a supervisor: 0.75 / 2.25');
